import { createHash } from 'node:crypto';
import type { LocalizedText, MediaScope, MediaVisibility } from '@bingoo/core';
import { db } from '@bingoo/db';
import type { Prisma } from '@bingoo/db';
import { getImage, getStorage, getTts } from '../providers';
import { initialModeration } from '../lib/media-moderation';
import { extForMime, renditionStorageKey } from '../lib/media-serialize';
import { createAsset, putRendition } from '../repos/media-asset.repo';
import { enrichAsset } from './media-enrich.service';

/**
 * AI media generation (docs/media-library-design.md §6). Generated bytes land in
 * the library as a normal MediaAsset so they are searchable, permissioned and
 * governed like everything else. Providers are PINNED per the product decision:
 * images → openai, audio → elevenlabs.
 *
 * CHILD-SAFETY (R5): a generated asset is NOT visible to children until it is
 * approved. It lands PENDING unless the caller already holds the approve button
 * (see `initialModeration`), in which case it is born APPROVED — the same decision
 * they would have made by hand. The prompt/model are recorded in
 * `metadata.generator` for the moderator's context + audit either way.
 */

const IMAGE_PROVIDER = 'openai';
const AUDIO_PROVIDER = 'elevenlabs';
const ACTIVE_STORAGE = process.env.STORAGE_PROVIDER ?? 'r2';

interface GenBase {
  folderId?: string | null;
  scope?: MediaScope;
  scopeId?: string | null;
  visibility?: MediaVisibility;
  title?: LocalizedText;
  /**
   * An asset generated with only a title — and an ENGLISH one, because the title
   * fell back to the generation prompt — is unfindable and unmoderatable: no
   * description for a reviewer to judge, no alt text for a screen reader, and a
   * Vietnamese search that will never match it. The caller knows what it asked
   * for in both languages; let it say so.
   */
  description?: LocalizedText;
  altText?: LocalizedText;
  createdById?: string | null;
  /** Creator's platform role — decides whether the asset is born PENDING or APPROVED. */
  createdByRole?: string | null;
}

/** Persist generated bytes as an asset with an ORIGINAL rendition in R2. */
async function persistGenerated(params: {
  base: GenBase;
  kind: 'IMAGE' | 'AUDIO';
  bytes: Uint8Array;
  mimeType: string;
  fallbackTitle: string;
  dims?: { width: number; height: number };
  generator: Prisma.InputJsonObject;
}) {
  const { base, kind, bytes, mimeType, fallbackTitle, dims, generator } = params;
  const title = base.title ?? { vi: fallbackTitle, en: fallbackTitle };
  const moderation = initialModeration(base.createdByRole);

  const asset = await createAsset({
    kind,
    title,
    ...(base.description ? { description: base.description } : {}),
    ...(base.altText ? { altText: base.altText } : {}),
    folderId: base.folderId ?? null,
    scope: base.scope,
    scopeId: base.scopeId ?? null,
    visibility: base.visibility ?? 'SCOPE',
    mimeType,
    source: `ai:${generator.provider as string}`,
    createdById: base.createdById ?? null,
    moderation,
  });

  const checksum = createHash('sha256').update(bytes).digest('hex');
  const key = renditionStorageKey(
    asset.scope,
    asset.scopeId,
    asset.id,
    'original',
    extForMime(mimeType),
  );
  await getStorage().putObject({ key, body: bytes, contentType: mimeType });
  await putRendition(asset.id, {
    kind: 'ORIGINAL',
    provider: ACTIVE_STORAGE,
    storageKey: key,
    checksum,
    mimeType,
    byteSize: bytes.byteLength,
  });
  // Record provenance for the moderator + audit; mark AI-generated. Store byte
  // size + pixel dims (when known) as typed, queryable metadata.
  await db.mediaAsset.update({
    where: { id: asset.id },
    data: {
      // PROCESSING is "waiting for a moderator" — the approve route is what promotes
      // it to READY. Born-approved bytes have nothing left to wait for.
      status: moderation === 'APPROVED' ? 'READY' : 'PROCESSING',
      byteSize: bytes.byteLength,
      checksum,
      width: dims?.width ?? undefined,
      height: dims?.height ?? undefined,
      metadata: { aiGenerated: true, generator },
    },
  });
  // Approved → run the full enrichment the approve route would have run. Otherwise
  // just index the embedding, so staff can find it while it awaits moderation.
  void enrichAsset(asset.id, moderation === 'APPROVED' ? {} : { embedOnly: true }).catch((e) =>
    console.error('[media.generate] enrich failed', e),
  );
  return asset;
}

export interface GenerateImageParams extends GenBase {
  prompt: string;
  /** tag slugs to attach — without them a generated asset is unfilterable */
  tagSlugs?: string[];
  size?: string;
  count?: number;
  /** Alpha handling — 'transparent' for sprites/overlays (see ImagePort). */
  background?: 'transparent' | 'opaque' | 'auto';
  /** Abort the provider call when a background job is cancelled. */
  signal?: AbortSignal;
}

/** Text-to-image via OpenAI → IMAGE asset(s), moderated per `initialModeration`. */
export async function generateImageAssets(params: GenerateImageParams) {
  const result = await getImage(IMAGE_PROVIDER).generate({
    prompt: params.prompt,
    size: params.size,
    count: params.count ?? 1,
    background: params.background,
    ...(params.signal ? { signal: params.signal } : {}),
  });

  const dims = parseSize(params.size);
  const assets = [];
  for (const img of result.images) {
    const bytes = await imageBytes(img);
    if (!bytes) continue;
    const asset = await persistGenerated({
      base: params,
      kind: 'IMAGE',
      bytes,
      mimeType: img.url && !img.b64 ? guessMimeFromUrl(img.url) : 'image/png',
      fallbackTitle: params.prompt.slice(0, 120),
      dims,
      generator: {
        provider: IMAGE_PROVIDER,
        model: result.model,
        prompt: params.prompt,
        size: params.size ?? null,
        background: params.background ?? null,
      },
    });
    assets.push(asset);
  }
  return assets;
}

/** Parse an OpenAI size string ("1024x1024") into typed pixel dimensions. */
function parseSize(size?: string): { width: number; height: number } | undefined {
  const m = /^(\d+)x(\d+)$/.exec(size ?? '');
  if (!m) return undefined;
  return { width: Number(m[1]), height: Number(m[2]) };
}

export interface GenerateAudioParams extends GenBase {
  text: string;
  voice?: string;
  languageCode?: string;
  /** Abort the provider call when a background job is cancelled. */
  signal?: AbortSignal;
}

/** Text-to-speech via ElevenLabs → an AUDIO asset, moderated per `initialModeration`. */
export async function generateAudioAsset(params: GenerateAudioParams) {
  const result = await getTts(AUDIO_PROVIDER).synthesize({
    text: params.text,
    voice: params.voice,
    languageCode: params.languageCode,
    ...(params.signal ? { signal: params.signal } : {}),
  });
  return persistGenerated({
    base: params,
    kind: 'AUDIO',
    bytes: result.audio,
    mimeType: result.contentType,
    fallbackTitle: params.text.slice(0, 120),
    generator: {
      provider: AUDIO_PROVIDER,
      voice: params.voice ?? null,
      languageCode: params.languageCode ?? null,
    },
  });
}

async function imageBytes(img: { b64?: string; url?: string }): Promise<Uint8Array | null> {
  if (img.b64) return new Uint8Array(Buffer.from(img.b64, 'base64'));
  if (img.url) {
    const res = await fetch(img.url);
    if (!res.ok) return null;
    return new Uint8Array(await res.arrayBuffer());
  }
  return null;
}

function guessMimeFromUrl(url: string): string {
  if (/\.png(\?|$)/i.test(url)) return 'image/png';
  if (/\.jpe?g(\?|$)/i.test(url)) return 'image/jpeg';
  if (/\.webp(\?|$)/i.test(url)) return 'image/webp';
  return 'image/png';
}
